//! Spec 037 (03 §13, D-87): the vendored Phosphor SVG files become a table of
//! flat contours in the binary at build time; no icon font and no SVG parsing
//! at run time. Coordinates are stored as hundredths of an icon unit in `i16`
//! (the grid is 256 units), so the generated file holds no float literal.

#![forbid(unsafe_code)]

use std::fmt::Write as _;
use std::path::{Path, PathBuf};
use std::{env, fs};

#[path = "src/icons/path_data.rs"]
mod path_data;

const WEIGHTS: [&str; 2] = ["fill", "regular"];

fn main() {
    let manifest = PathBuf::from(env::var("CARGO_MANIFEST_DIR").expect("cargo sets it"));
    let root = manifest.join("../../assets/icons/phosphor");
    println!("cargo:rerun-if-changed=src/icons/path_data.rs");
    println!("cargo:rerun-if-changed={}", root.display());
    let mut entries: Vec<(String, Vec<path_data::Contour>)> = Vec::new();
    for weight in WEIGHTS {
        let dir = root.join(weight);
        println!("cargo:rerun-if-changed={}", dir.display());
        for path in svg_files(&dir) {
            println!("cargo:rerun-if-changed={}", path.display());
            let stem = path
                .file_stem()
                .and_then(|s| s.to_str())
                .expect("UTF-8 file name");
            let svg = fs::read_to_string(&path).expect("readable icon");
            let contours =
                path_data::svg_contours(&svg).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
            entries.push((format!("{weight}/{stem}"), contours));
        }
    }
    // Gafira's own icons (not Phosphor), one weight, keyed `gafira/<name>`.
    let own = manifest.join("../../assets/icons/gafira");
    println!("cargo:rerun-if-changed={}", own.display());
    for path in svg_files(&own) {
        println!("cargo:rerun-if-changed={}", path.display());
        let stem = path
            .file_stem()
            .and_then(|s| s.to_str())
            .expect("UTF-8 file name");
        let svg = fs::read_to_string(&path).expect("readable icon");
        let contours =
            path_data::svg_contours(&svg).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
        entries.push((format!("gafira/{stem}"), contours));
    }
    entries.sort_by(|a, b| a.0.cmp(&b.0));
    let mut out = String::from(
        "// @generated by build.rs from assets/icons/phosphor and assets/icons/gafira (spec 037); do not edit.\n\
         /// Every vendored icon by `weight/name`, sorted; contours in hundredths of a unit.\n\
         pub(crate) static GEOMETRY: &[(&str, &[&[[i16; 2]]])] = &[\n",
    );
    for (key, contours) in &entries {
        let _ = write!(out, "    ({key:?}, &[");
        for contour in contours {
            out.push_str("&[");
            for p in contour {
                let _ = write!(out, "[{}, {}],", fixed(p[0]), fixed(p[1]));
            }
            out.push_str("],");
        }
        out.push_str("]),\n");
    }
    out.push_str("];\n");
    let target = PathBuf::from(env::var("OUT_DIR").expect("cargo sets it")).join("icons.rs");
    fs::write(target, out).expect("writable OUT_DIR");
}

/// The SVG files of `dir`, sorted; a missing folder has none.
fn svg_files(dir: &Path) -> Vec<PathBuf> {
    let Ok(read) = fs::read_dir(dir) else {
        return Vec::new();
    };
    let mut files: Vec<PathBuf> = read
        .flatten()
        .map(|e| e.path())
        .filter(|p| p.extension().is_some_and(|e| e == "svg"))
        .collect();
    files.sort();
    files
}

/// A coordinate in hundredths of an icon unit. Every icon stays within the
/// 256-unit grid (DIS-50), so the value fits `i16` with room to spare.
fn fixed(value: f32) -> i16 {
    assert!(
        (0.0..=path_data::GRID).contains(&value),
        "coordinate {value} is outside the icon grid"
    );
    (value * 100.0).round() as i16
}
